$(document).ready(function(){$("#loginBtn").on("click",function(e){e.preventDefault(),$.ajax({type:"POST",dataType:"json",data:$("#login").serialize(),success:function(e){200==e.status?window.location.href="//"+document.domain+e.url:alert(e.msg)},error:function(e){console.log(e)}})}),$("#registerBtn").on("click",function(e){e.preventDefault(),$.ajax({type:"POST",dataType:"json",data:$("#register").serialize(),success:function(e){200==e.status?window.location.href="//"+document.domain+e.url:alert(e.msg)},error:function(e){console.log(e)}}),e.preventDefault()}),$("#forgotPassword").on("click",function(e){e.preventDefault(),$.ajax({type:"POST",dataType:"json",data:$("#forgot").serialize(),success:function(e){200==e.status?($(".beforeClick").hide(),$(".afterClick").show(),$("#statusMsg").text(e.msg),console.log(e.msg)):alert(e.msg)},error:function(e){console.log(e)}})}),$("#updatePassword").on("click",function(e){e.preventDefault(),$.ajax({type:"POST",dataType:"json",data:$("#update").serialize(),success:function(e){200==e.status?($(".beforeClick").hide(),$(".afterClick").show(),$("#statusMsg").text(e.msg)):alert(e.msg)},error:function(e){console.log(e)}})})});